def fizz_buzz(n: int) -> int:
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13."""
    if n <= 0:
        return 0

    digits = [int(c) for c in str(n)]

    # dp[mod11][mod13][tight] = (count, total_sevens)
    dp = [[[(0, 0) for _ in range(2)] for _ in range(13)] for _ in range(11)]
    dp[0][0][1] = (1, 0)

    for bound in digits:
        new_dp = [[[(0, 0) for _ in range(2)] for _ in range(13)] for _ in range(11)]

        for m11 in range(11):
            for m13 in range(13):
                for tight in range(2):
                    cnt, sevens = dp[m11][m13][tight]
                    if cnt == 0:
                        continue

                    limit = bound if tight else 9
                    for d in range(limit + 1):
                        ntight = 1 if (tight and d == bound) else 0
                        nm11 = (m11 * 10 + d) % 11
                        nm13 = (m13 * 10 + d) % 13

                        ncnt, nsevens = new_dp[nm11][nm13][ntight]
                        new_dp[nm11][nm13][ntight] = (
                            ncnt + cnt,
                            nsevens + sevens + (cnt if d == 7 else 0)
                        )

        dp = new_dp

    ans = 0
    for m11 in range(11):
        for m13 in range(13):
            if m11 == 0 or m13 == 0:
                ans += dp[m11][m13][0][1]

    return ans


