        if ',' in s and '.' in s:
            if s.rfind(',') > s.rfind('.'):
                # Example: "1.234,56" -> comma is decimal, dot is thousands separator
                s = s.replace('.', '').replace(',', '.')
            else:
                # Example: "1,234.56" -> dot is decimal, comma is thousands separator
                s = s.replace(',', '')
        elif ',' in s:
            s = s.replace(',', '.')

        return Decimal(s)

